168	    /**
169	     * The owner's name formatted as {@code 'LastName, FirstName'} from the stored names.
170	     */
171	    public String getDisplayName() {
172	        return this.getLastName() + ", " + this.getFirstName();
173	    }
174	
175	    /**
176	     * The owner's initials: the upper-cased first letters of firstName and lastName,
177	     * dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
178	     */
179	    public String getInitials() {
180	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
181	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
182	    }
183	
184	    /**
185	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is the
186	     * last two digits of the registrationDate year, e.g. {@code 'LON-SMI-0007-M26'}.
187	     */
188	    public String getMembershipNumber() {
189	        return this.customerCode + "-M" + String.format("%02d", this.registrationDate.getYear() % 100);
190	    }
191	
192	    /** Fixed city-to-region table used to derive an owner's locality. */
193	    private static final Map<String, String> CITY_REGION = Map.of(
194	        "Sydney", "NSW",
195	        "Melbourne", "VIC",
196	        "Brisbane", "QLD");
197	
198	    /** The region reported for a city that is not present in {@link #CITY_REGION}. */
199	    public static final String UNKNOWN_REGION = "UNKNOWN";
200	
201	    /**
202	     * The canonical region for a city, derived from the fixed city-to-region table
203	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}), or
204	     * {@link #UNKNOWN_REGION} when the city is not in the table. This is the single
205	     * source of the city-to-region mapping, shared by every rule that is keyed by
206	     * region so the mapping is never re-derived elsewhere.
207	     */
208	    public static String regionOf(String city) {
209	        return CITY_REGION.getOrDefault(city, UNKNOWN_REGION);
210	    }
211	
212	    /**
213	     * The owner's locality: the {@linkplain #regionOf(String) canonical region} of the
214	     * owner's city, or {@link #UNKNOWN_REGION} when the city has no known region.
215	     */
216	    public String getLocality() {
217	        return regionOf(this.city);
218	    }
219	
220	    /**
221	     * Fixed inclusive 4-digit postcode ranges keyed by region, as {@code {low, high}}:
222	     * {@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}. A region not
223	     * listed here (i.e. {@link #UNKNOWN_REGION}) accepts any 4-digit postcode.
224	     */
225	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
226	        "NSW", new int[] {2000, 2099},
227	        "VIC", new int[] {3000, 3099},
228	        "QLD", new int[] {4000, 4099});
229	
230	    /**
231	     * Whether this owner's postcode is acceptable for its city. Postcode is optional, so a
232	     * {@code null} postcode is accepted. When present it must be four digits and, for a city
233	     * whose {@linkplain #regionOf(String) region} is known, fall within that region's fixed
234	     * inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}); a
235	     * city with no known region accepts any 4-digit postcode.
236	     */
237	    public boolean isPostcodeValid() {
238	        if (this.postcode == null) {
239	            return true;
240	        }
241	        if (!this.postcode.matches("[0-9]{4}")) {
242	            return false;
243	        }
244	        int[] range = REGION_POSTCODE_RANGE.get(regionOf(this.city));
245	        if (range == null) {
246	            return true;
247	        }
248	        int value = Integer.parseInt(this.postcode);
249	        return value >= range[0] && value <= range[1];
250	    }
251	
252	    /**
253	     * The owner's membership level, a number from 1 to 3 determined on creation: it starts at 1,
254	     * gains 1 when an email is present, gains 1 when namesakeCount is 0, and is capped at 3.
255	     * Level 4 is reserved for tenure.
256	     */
257	    public Integer getMembershipLevel() {
258	        int level = 1;
259	        if (this.email != null && !this.email.isEmpty()) {
260	            level++;
261	        }
262	        if (this.namesakeCount != null && this.namesakeCount == 0) {
263	            level++;
264	        }
265	        return Math.min(level, 3);
266	    }
267	
268	    /**
269	     * The owner's preferred contact channel: {@code 'EMAIL'} when an email is present,
270	     * otherwise {@code 'PHONE'}.
271	     */
272	    public String getContactPreference() {
273	        return (this.email != null && !this.email.isEmpty()) ? "EMAIL" : "PHONE";
274	    }
275	
276	    /**
277	     * The owner's identity key: the single derived value used for duplicate detection.
278	     * It joins the normalized (E.164) telephone, the email (already lower-cased, or the
279	     * empty string when absent) and the householdId (or the empty string when the owner
280	     * has no household) with {@code '|'}, e.g. {@code '+61412345678|jane@example.test|3C1A9F2B7D4E'}.
281	     * Two owners are duplicates only when their whole identity keys are equal.
282	     */
283	    public String getIdentityKey() {
284	        String telephonePart = this.telephone == null ? "" : this.telephone;
285	        String emailPart = this.email == null ? "" : this.email;
286	        String householdPart = this.householdId == null ? "" : this.householdId;
287	        return telephonePart + "|" + emailPart + "|" + householdPart;
288	    }
289	
290	    protected Set<Pet> getPetsInternal() {
291	        if (this.pets == null) {
292	            this.pets = new HashSet<>();
293	        }
294	        return this.pets;
295	    }
296	
297	    protected void setPetsInternal(Set<Pet> pets) {
298	        this.pets = pets;
299	    }
300	
301	    public List<Pet> getPets() {
302	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
303	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
304	        return Collections.unmodifiableList(sortedPets);
305	    }
306	
307	    public void setPets(List<Pet> pets) {
308	        this.pets = new HashSet<>(pets);
309	    }
310	
311	    public void addPet(Pet pet) {
312	        getPetsInternal().add(pet);
313	        pet.setOwner(this);
314	    }
315	
316	    /**
317	     * Return the Pet with the given name, or null if none found for this Owner.
318	     *
319	     * @param name to test
320	     * @return true if pet name is already in use
321	     */
322	    public Pet getPet(String name) {
323	        return getPet(name, false);
324	    }
325	
326	    /**
327	     * Return the Pet with the given name, or null if none found for this Owner.
328	     *
329	     * @param name to test
330	     * @return true if pet name is already in use
331	     */
332	    public Pet getPet(String name, boolean ignoreNew) {
333	        name = name.toLowerCase();
334	        for (Pet pet : getPetsInternal()) {
335	            if (!ignoreNew || !pet.isNew()) {
336	                String compName = pet.getName();
337	                compName = compName.toLowerCase();
338	                if (compName.equals(name)) {
339	                    return pet;
340	                }
341	            }
342	        }
343	        return null;
344	    }
345	
346	    public Pet getPet(Integer petId) {
347	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
348	    }
349	
350	    @Override
351	    public String toString() {
352	        return new ToStringCreator(this)
353	
354	            .append("id", this.getId())
355	            .append("new", this.isNew())
356	            .append("lastName", this.getLastName())
357	            .append("firstName", this.getFirstName())
358	            .append("address", this.address)
359	            .append("city", this.city)
360	            .append("telephone", this.telephone)
361	            .append("email", this.email)
362	            .toString();
363	    }
364	}
